#!/bin/sh
set -eu

rm -rf dist
mkdir -p dist/assets

cp index.html international.html digital-ai.html education-hr.html readiness.html agro-tag.html README.txt dist/ 2>/dev/null || true

if [ -d assets ]; then
  cp -R assets/. dist/assets/
fi

# Stable public aliases for manually uploaded visual assets.
cp "ChatGPT Image 30 авг. 2026 г., 12_21_44.png" dist/assets/regional-business-white.png
cp "Serbian market.png" dist/assets/projects-serbia.png
cp "Technical project.png" dist/assets/projects-tech.png
cp "book publishing.png" dist/assets/projects-publishing.png
cp "nizkii-ugol-zrenia-ofisnogo-zdania.jpg" dist/assets/digital-transformation-hero.jpg
cp "Plum Sum.png" dist/assets/project-plum-sum.png
cp "сельскохозяйственный_комплекс_на_закате.png" dist/assets/project-agriculture.png
cp "современная_лаборатория_учёные_за_работой.png" dist/assets/project-laboratory.png
cp "Bank.png" dist/assets/project-bank.png

# Turn the AGRO TAG product list into a visual product showcase and refine the partner section.
python - <<'PY'
from pathlib import Path
p = Path('dist/agro-tag.html')
s = p.read_text(encoding='utf-8')
old_css = '''.products{position:relative;background:#fff;overflow:hidden}.products:before{display:none}.products .wrap{position:relative;z-index:2}.products .kicker{color:var(--rose)}.products h2{color:var(--deep)}.products-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:13px}.product{position:relative;padding:23px 25px;display:grid;grid-template-columns:52px 1fr;gap:17px;border-radius:18px;background:linear-gradient(180deg,#fafbfb 0%,#f0f3f4 100%);border:1px solid rgba(72,105,133,.12);box-shadow:0 10px 24px rgba(41,62,82,.04);overflow:hidden}.product:before{content:"";position:absolute;left:0;top:0;bottom:0;width:3px;background:var(--blue)}.product:nth-child(3n):before{background:var(--rose)}.product span{color:var(--blue);font-size:24px;font-weight:800;letter-spacing:.06em}.product:nth-child(3n) span{color:var(--rose)}.product h3{color:var(--deep);font-size:24px}.product p{margin-top:8px;color:#667786;font-size:13px;line-height:1.55}'''
new_css = '''.products{position:relative;background:#fff;overflow:hidden}.products:before{display:none}.products .wrap{position:relative;z-index:2}.products .kicker{color:var(--rose)}.products h2{color:var(--deep)}.products .section-head .lead{max-width:560px;font-size:18px;line-height:1.65}.products-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px}.product{position:relative;min-height:360px;border-radius:22px;background:#fff;border:1px solid rgba(72,105,133,.12);box-shadow:0 16px 34px rgba(41,62,82,.08);overflow:hidden;display:flex;flex-direction:column;transition:transform .3s ease,box-shadow .3s ease}.product:hover{transform:translateY(-4px);box-shadow:0 22px 44px rgba(41,62,82,.12)}.product-media{height:185px;overflow:hidden;background:#e9eef0}.product-media img{width:100%;height:100%;object-fit:cover;object-position:center;transition:transform .45s ease}.product:hover .product-media img{transform:scale(1.035)}.product-body{position:relative;padding:20px 21px 22px;flex:1}.product-num{display:block;color:var(--blue);font-size:30px;font-weight:800;line-height:1;letter-spacing:.04em}.product:nth-child(3n+2) .product-num{color:var(--green)}.product:nth-child(3n) .product-num{color:var(--rose)}.product h3{margin-top:9px;color:var(--deep);font-size:22px;line-height:1.1}.product p{margin-top:10px;color:#44566a;font-size:13.5px;line-height:1.52}.product.service-card .product-media img{object-position:center 35%}@media(max-width:980px){.products-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:700px){.products-grid{grid-template-columns:1fr}.product{min-height:auto}.product-media{height:220px}.products .section-head .lead{font-size:16px}}'''
old_section = '''<section class="products" id="products"><div class="wrap"><div class="section-head"><div><div class="kicker">Продуктовые направления</div><h2>Группы продукции и технологий</h2></div><p class="lead">Конкретные модели и комплектации подбираются после анализа культур, хозяйств, тракторного парка и коммерческого потенциала рынка. Будущий портфель Партнёра формируется модульно: начать можно с приоритетных групп и расширять предложение по мере роста рынка.</p></div><div class="products-grid"><article class="product"><span>01</span><div><h3>Обработка почвы</h3><p>Бороны, дисковые орудия, культиваторы, фрезы, ротационные бороны, глубокорыхлители.</p></div></article><article class="product"><span>02</span><div><h3>Посев</h3><p>Механические и пневматические сеялки для зерновых, пропашных и овощных культур.</p></div></article><article class="product"><span>03</span><div><h3>Защита растений</h3><p>Навесные и прицепные опрыскиватели, садовые и виноградниковые атомайзеры.</p></div></article><article class="product"><span>04</span><div><h3>Овощи и корнеплоды</h3><p>Посадка, уход, уборка, транспортировка и послеуборочная обработка.</p></div></article><article class="product"><span>05</span><div><h3>Ягодоводство</h3><p>Подготовка плантаций и механизированная уборка.</p></div></article><article class="product"><span>06</span><div><h3>Транспорт и инфраструктура</h3><p>Прицепы, резервуары, ёмкости, навесы, ограждения и металлоконструкции.</p></div></article><article class="product"><span>07</span><div><h3>Сервисная экосистема</h3><p>Запчасти, расходные материалы, обучение, диагностика и ввод в эксплуатацию.</p></div></article><article class="product"><span>08</span><div><h3>Кошение, кормозаготовка и мульчирование</h3><p>Дисковые и сегментные косилки, грабли и ворошилки для сена, мульчеры для полей, садов и виноградников.</p></div></article></div></div></section>'''
new_section = '''<section class="products" id="products"><div class="wrap"><div class="section-head"><div><div class="kicker">Продуктовые направления</div><h2>Группы продукции и технологий</h2></div><p class="lead">Конкретные модели и комплектации подбираются после анализа культур, хозяйств, тракторного парка и коммерческого потенциала рынка. Будущий портфель Партнёра формируется модульно: начать можно с приоритетных групп и расширять предложение по мере роста рынка.</p></div><div class="products-grid"><article class="product"><div class="product-media"><img src="https://shop.fpm.rs/media/catalogProduct/teskaFrezaRotas2606/FPM-ROTAS.png" alt="Техника для обработки почвы"/></div><div class="product-body"><span class="product-num">01</span><h3>Обработка почвы</h3><p>Бороны, дисковые орудия, культиваторы, фрезы, ротационные бороны, глубокорыхлители.</p></div></article><article class="product"><div class="product-media"><img src="https://agria.rs/wp-content/uploads/2023/08/zitka-featured-image.webp" alt="Посевная техника"/></div><div class="product-body"><span class="product-num">02</span><h3>Посев</h3><p>Механические и пневматические сеялки для зерновых, пропашных и овощных культур.</p></div></article><article class="product"><div class="product-media"><img src="https://bsk.rs/uploads/ck_editor/images/Rotoprotect-home.jpg" alt="Система защиты растений"/></div><div class="product-body"><span class="product-num">03</span><h3>Защита растений</h3><p>Навесные и прицепные опрыскиватели, садовые и виноградниковые системы защиты.</p></div></article><article class="product"><div class="product-media"><img src="https://agria.rs/wp-content/uploads/2023/08/psp-agria-img.webp" alt="Техника для овощей и корнеплодов"/></div><div class="product-body"><span class="product-num">04</span><h3>Овощи и корнеплоды</h3><p>Посадка, уход, уборка, транспортировка и послеуборочная обработка.</p></div></article><article class="product"><div class="product-media"><img src="https://site.caes.uga.edu/smallfruits/files/2022/07/BBHarvest-Photo1-1024x678.jpg" alt="Механизированная уборка ягод"/></div><div class="product-body"><span class="product-num">05</span><h3>Ягодоводство</h3><p>Подготовка плантаций, защита насаждений и механизированная уборка ягод.</p></div></article><article class="product"><div class="product-media"><img src="https://www.lifam-m.com/wp-content/uploads/2022/04/Nenaslovljeni-dizajn-1.jpg" alt="Сельскохозяйственная инфраструктура и оборудование"/></div><div class="product-body"><span class="product-num">06</span><h3>Транспорт и инфраструктура</h3><p>Прицепы, резервуары, ёмкости, навесы, ограждения и металлоконструкции.</p></div></article><article class="product service-card"><div class="product-media"><img src="https://agria.rs/wp-content/uploads/2023/08/services-agria-image.webp" alt="Сервис сельскохозяйственной техники"/></div><div class="product-body"><span class="product-num">07</span><h3>Сервисная экосистема</h3><p>Запчасти, расходные материалы, обучение, диагностика и ввод в эксплуатацию.</p></div></article><article class="product"><div class="product-media"><img src="https://www.fpm.rs/media/catalogProduct/mulcarZaRatarstvo/Mulcar-za-ratarstvo-1.png" alt="Техника для кошения и мульчирования"/></div><div class="product-body"><span class="product-num">08</span><h3>Кошение, кормозаготовка и мульчирование</h3><p>Косилки, грабли, ворошилки и мульчеры для полей, садов и виноградников.</p></div></article></div></div></section>'''
if old_css not in s:
    raise SystemExit('AGRO TAG product CSS block not found')
if old_section not in s:
    raise SystemExit('AGRO TAG product section not found')
s = s.replace(old_css, new_css, 1).replace(old_section, new_section, 1)

old_partner_css = '''.partner{background:linear-gradient(180deg,#f7f9f9 0%,#eef2f3 100%);border-top:1px solid rgba(72,105,133,.10)}.partner-shell{display:grid;grid-template-columns:.9fr 1.1fr;gap:50px;align-items:start}.partner .kicker{color:var(--rose)}.partner h2{max-width:10ch;color:var(--deep)}.criteria{display:grid;gap:11px}.criterion{padding:19px 21px;border:1px solid rgba(72,105,133,.12);border-radius:16px;background:rgba(255,255,255,.78);display:flex;gap:16px;align-items:flex-start;box-shadow:0 8px 20px rgba(41,62,82,.035)}.criterion:before{content:"";width:12px;height:12px;margin-top:6px;background:var(--blue);transform:rotate(45deg);border-radius:2px;flex:0 0 auto}.criterion:nth-child(3):before{background:var(--rose)}.criterion span{color:#46596b;line-height:1.6}'''
new_partner_css = '''.partner{position:relative;background:linear-gradient(180deg,#f5f7f7 0%,#eaf0f1 100%);border-top:1px solid rgba(72,105,133,.16);overflow:hidden}.partner:before{content:"";position:absolute;left:0;top:0;width:34%;height:4px;background:linear-gradient(90deg,var(--rose),var(--blue));z-index:1}.partner .wrap{position:relative;z-index:2}.partner-shell{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:38px;align-items:start}.partner .kicker{color:var(--rose);font-family:var(--serif);font-weight:600;letter-spacing:-.01em;text-transform:none;font-size:20px}.partner-left h2{max-width:8ch;color:var(--deep);font-size:clamp(42px,4.4vw,60px);line-height:.96}.partner-left .lead{margin-top:24px;max-width:410px;color:#596b7c;font-size:16px;line-height:1.72}.partner-middle{padding-top:55px}.criteria-list{margin:0;padding:0;list-style:none;display:grid;gap:18px}.criteria-list li{position:relative;padding:0 0 18px 22px;border-bottom:1px solid rgba(72,105,133,.14);color:#46596b;font-size:15.5px;line-height:1.58}.criteria-list li:last-child{border-bottom:0}.criteria-list li:before{content:"";position:absolute;left:1px;top:.48em;width:9px;height:9px;background:var(--blue);transform:rotate(45deg);border-radius:1px}.criteria-list li:nth-child(3):before{background:var(--rose)}.partner-right{min-height:430px}.partner-image-placeholder{position:relative;width:100%;height:430px;border-radius:24px;overflow:hidden;background:linear-gradient(145deg,#e6ecee 0%,#d5e0e2 54%,#c5d3d8 100%);box-shadow:0 18px 38px rgba(41,62,82,.10)}.partner-image-placeholder:before{content:"";position:absolute;left:-8%;right:-8%;bottom:-14%;height:62%;background:linear-gradient(165deg,rgba(72,105,133,.16),rgba(173,98,107,.08));clip-path:polygon(0 62%,24% 35%,43% 58%,63% 20%,82% 52%,100% 28%,100% 100%,0 100%)}.partner-image-placeholder:after{content:"";position:absolute;left:22px;top:22px;width:64px;height:5px;border-radius:999px;background:linear-gradient(90deg,var(--rose) 0 40%,var(--blue) 40% 76%,#b9c9cf 76%)}@media(max-width:980px){.partner-shell{grid-template-columns:1fr;gap:28px}.partner-middle{padding-top:0}.partner-left h2{max-width:11ch}.partner-right,.partner-image-placeholder{min-height:320px;height:320px}}'''
old_partner_section = '''<section class="partner" id="partner"><div class="wrap partner-shell"><div><div class="kicker">Профиль партнёра</div><h2>Сильный оператор рынка, готовый строить систему</h2><p class="lead" style="margin-top:24px">Наличие всей инфраструктуры на старте не обязательно. Критичны репутация, доступ к клиентам, выделенная команда и готовность выполнять согласованный план развития.</p></div><div class="criteria"><div class="criterion"><span>Финансовая устойчивость и деловая репутация.</span></div><div class="criterion"><span>Доступ к фермерам, агрохолдингам и отраслевым организациям.</span></div><div class="criterion"><span>Выделенный руководитель направления и коммерческая команда.</span></div><div class="criterion"><span>Готовность развивать продажи нескольких групп продукции.</span></div><div class="criterion"><span>Способность организовать импорт, логистику и локальный сервис.</span></div></div></div></section>'''
new_partner_section = '''<section class="partner" id="partner"><div class="wrap partner-shell"><div class="partner-left"><div class="kicker">Приглашаем к партнёрству</div><h2>Сильный оператор рынка, готовый строить систему</h2><p class="lead">Наличие всей инфраструктуры на старте не обязательно. Критичны репутация, доступ к клиентам, выделенная команда и готовность выполнять согласованный план развития.</p></div><div class="partner-middle"><ul class="criteria-list"><li>Финансовая устойчивость и деловая репутация.</li><li>Доступ к фермерам, агрохолдингам и отраслевым организациям.</li><li>Выделенный руководитель направления и коммерческая команда.</li><li>Готовность развивать продажи нескольких групп продукции.</li><li>Способность организовать импорт, логистику и локальный сервис.</li></ul></div><div class="partner-right"><div class="partner-image-placeholder" role="img" aria-label="Место для изображения сельхозугодий в горной местности Центральной Азии"></div></div></div></section>'''
if old_partner_css not in s:
    raise SystemExit('AGRO TAG partner CSS block not found')
if old_partner_section not in s:
    raise SystemExit('AGRO TAG partner section not found')
s = s.replace(old_partner_css, new_partner_css, 1).replace(old_partner_section, new_partner_section, 1)

p.write_text(s, encoding='utf-8')
PY

if [ -d en ]; then cp -R en dist/en; fi
if [ -d cz ]; then cp -R cz dist/cz; fi

cp home-premium.css dist/home-premium.css
cp international-hero.css dist/international-hero.css
cp partners-ecosystem.css dist/partners-ecosystem.css

touch dist/.nojekyll
